Definition su_t70 : plan := subL 70 startup_plan.
Definition su_K (i : nat) : plan := nth i (psubs 24 (pkid 0 su_t70)) PContra.

(* [comment removed for export] *)
Definition su_SB : expr := EAlu Instr.ALU_ADD (EMd Instr.M_MUL (ELit 32768) (EVar 0)) (EMd Instr.M_MUL (ELit 16) (EVar 6)).
Definition su_KD : kentry := KDisj (SA su_SB (-8388608)) (ELit 16777216) (SA (EMd Instr.M_MUL (ELit 4096) (EVar 93)) 0) (ELit 65536).

(* [comment removed for export] *)
Definition su_P1_plan : plan := ins_main 37 (PFact su_KD) (fst (pcutS 200 70 startup_plan 0)).   (* [comment removed for export] *)
Definition su_P1_tab : nat -> option acs := hs_tab [(1000%nat, HS_s1c_1000)].

(* [comment removed for export] *)
